import axios from "axios";
// 本地静态图片

// 滑块组件


export default {
  name: "Login",
  components: {
    Sidentify,
  },
  data() {
    return {
      isPassing: false,
      value: "",
      imgsrc: "http://celiang.oss-cn-hangzhou.aliyuncs.com/measurement/2022-04/26/uAFwlphpXmYIyH1650941449220426.jpg",
      isLogin: true,
      identifyCodes: "1234567890", //验证码的数字库
      identifyCode: "",  // 验证码组件传值
      gzh: gzh,
      zhuoda: zhuoda,
      loginQR: loginQR,
      wechatIcon: wechatIcon,
      aliIcon: aliIcon,
      douyinIcon: douyinIcon,
      qqIcon: qqIcon,
      weiboIcon: weiboIcon,
      feishuIcon: feishuIcon,
      googleIcon: googleIcon,
      registerForm: {
        registerName: '',
        password: '',
        repassword: '',
        role: 'student',
        captchaCode: '',
        // loginDevice: LOGIN_DEVICE_ENUM.PC.value,
      },
      rules: {
        registerName: [
          {min: 3, max: 8, message: '长度在 3 到 8 个字符'},
          {required: true, message: '请输入用户名', trigger: ['blur', 'change']}
        ],
        password: [
          {min: 6, max: 20, message: '长度在 6 到 20 个字符'},
          // 密码 格式
          {
            pattern: /^(?![0-9]+$)(?![a-zA-Z]+$)[0-9A-Za-z]{6,20}$/,
            message: '密码由字母和数字组成，且长度在6-20位',
            trigger: 'blur'
          },

          {required: true, message: '请输入密码', trigger: ['blur', 'change']}
        ],
        repassword: [
          {required: true, message: '请输入密码', trigger: ['blur', 'change']}
        ],
        captchaCode: [
          {required: true, message: '请输入验证码', trigger: ['blur', 'change']}
        ],
      },

    }
  },

  created() {
    this.refreshCode(); //初始化验证码
  },
  mounted() {
    // 验证码初始化
    this.identifyCode = '';
    this.makeCode(this.identifyCodes, 4);
  },

  methods: {
    goLogin() {
      this.$router.push({path: '/login'})
    },
    async registerSubmit() {
      console.log('identifyCode', this.identifyCode)
      if (this.registerForm.registerName === '') {
        this.$message.error('请输入用户名');
        return;

      } else if (this.registerForm.password === '') {
        this.$message.error('请输入密码');
        return;
      } else if (this.registerForm.repassword === '') {
        this.$message.error('请输入密码');
        return;
      } else if (this.registerForm.repassword !== this.registerForm.password) {
        this.$message.error('两次密码不一致，请重新输入！');
        return;
      } else if (this.registerForm.captchaCode !== this.identifyCode) {
        this.$message.error('验证码错误');
        this.refreshCode();
        return;
      }
      console.log('registerForm  ', this.registerForm);
      // axios.post 像后端传递 form 对象
      await axios.post('/api/register', this.registerForm)
          .then(response => {
            // 将响应数据赋值给 title
            console.log("注册 ", response.data);
            if (response.data === "该用户名已被注册！") {
              this.$message.error('该用户名已被注册！');
              return
            } else {
              this.$message.success('注册成功！');
              this.$router.push({path: '/login'})
            }
          })
          .catch(error => {
            console.log(error);
          });
    },
    QRlogin() {
      // 提示该方式登录不可用
      this.$message.error('该登录方式暂不可用！');
    },
    //验证码----start
    randomNum(min, max) {
      return Math.floor(Math.random() * (max - min) + min);
    },
    refreshCode() {
      this.identifyCode = "";
      this.makeCode(this.identifyCodes, 4);
    },
    makeCode(o, l) {
      for (let i = 0; i < l; i++) {
        this.identifyCode += this.identifyCodes[
            this.randomNum(0, this.identifyCodes.length)
            ];
      }
      console.log("this.identifyCode:", this.identifyCode);
    },
    //验证码----end

  }
};
</script>
